-- Acme Robotics orders (fictional). Generated by make_orders.py; do not edit.
-- 'Today' for every question about this data is 2026-10-28.
CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, region TEXT NOT NULL, account_tier TEXT NOT NULL, email TEXT NOT NULL);
CREATE TABLE products (sku TEXT PRIMARY KEY, model TEXT NOT NULL, unit_price INTEGER NOT NULL, lead_time_days INTEGER NOT NULL);
CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), placed_at TEXT NOT NULL, status TEXT NOT NULL, hold_reason TEXT, carrier TEXT, tracking_no TEXT, promised_by TEXT NOT NULL, shipped_at TEXT, delivered_at TEXT);
CREATE TABLE order_items (order_id INTEGER NOT NULL REFERENCES orders(id), sku TEXT NOT NULL REFERENCES products(sku), qty INTEGER NOT NULL);
CREATE TABLE shipments (order_id INTEGER NOT NULL REFERENCES orders(id), seq INTEGER NOT NULL, event TEXT NOT NULL, at TEXT NOT NULL, location TEXT NOT NULL, PRIMARY KEY (order_id, seq));
